<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>2048</title>
<style>
  :root {
    --bg: #121213;
    --board-bg: #1f1f22;
    --cell-bg: #2b2b30;
    --text: #eee;
    --accent: #f2b179;
  }
  * { box-sizing: border-box; }
  body {
    margin: 0;
    min-height: 100vh;
    background: var(--bg);
    color: var(--text);
    font-family: "Segoe UI", Arial, sans-serif;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 16px;
    padding: 20px;
  }
  h1 {
    margin: 0;
    letter-spacing: 4px;
  }
  #topbar {
    display: flex;
    align-items: center;
    gap: 20px;
  }
  #scoreBox {
    background: var(--board-bg);
    padding: 10px 18px;
    border-radius: 8px;
    text-align: center;
    min-width: 90px;
  }
  #scoreBox .label {
    font-size: 12px;
    opacity: 0.6;
    text-transform: uppercase;
  }
  #score {
    font-size: 22px;
    font-weight: bold;
  }
  #reset {
    background: var(--accent);
    color: #222;
    border: none;
    padding: 10px 18px;
    border-radius: 8px;
    font-weight: bold;
    cursor: pointer;
    font-size: 14px;
  }
  #reset:hover {
    filter: brightness(1.1);
  }
  #board {
    display: grid;
    grid-template-columns: repeat(4, 80px);
    grid-template-rows: repeat(4, 80px);
    gap: 10px;
    background: var(--board-bg);
    padding: 10px;
    border-radius: 10px;
  }
  .cell {
    width: 80px;
    height: 80px;
    border-radius: 6px;
    background: var(--cell-bg);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 28px;
    font-weight: bold;
    color: #776e65;
    transition: background 0.1s ease;
  }
  .cell[data-v="0"] { color: transparent; }
  .cell[data-v="2"] { background: #3a3a40; color: #eee; }
  .cell[data-v="4"] { background: #45443f; color: #eee; }
  .cell[data-v="8"] { background: #c07b45; color: #fff; }
  .cell[data-v="16"] { background: #c76a3a; color: #fff; }
  .cell[data-v="32"] { background: #c85f42; color: #fff; }
  .cell[data-v="64"] { background: #d1462a; color: #fff; }
  .cell[data-v="128"] { background: #d9c14e; color: #fff; font-size: 24px; }
  .cell[data-v="256"] { background: #d9bb3c; color: #fff; font-size: 24px; }
  .cell[data-v="512"] { background: #d9b42a; color: #fff; font-size: 24px; }
  .cell[data-v="1024"] { background: #d9ac17; color: #fff; font-size: 20px; }
  .cell[data-v="2048"] { background: #d9a400; color: #fff; font-size: 20px; }
  #hint {
    opacity: 0.5;
    font-size: 13px;
  }
</style>
</head>
<body>

<h1>2048</h1>
<div id="topbar">
  <div id="scoreBox">
    <div class="label">Score</div>
    <div id="score">0</div>
  </div>
  <button id="reset">New Game</button>
</div>
<div id="board"></div>
<div id="hint">Use arrow keys to play</div>

<script>
(function() {
  const SIZE = 4;
  let board = [];
  let score = 0;

  const boardEl = document.getElementById('board');
  const scoreEl = document.getElementById('score');
  const resetBtn = document.getElementById('reset');

  function emptyBoard() {
    return Array.from({length: SIZE}, () => Array(SIZE).fill(0));
  }

  function getEmptyCells(b) {
    const cells = [];
    for (let r = 0; r < SIZE; r++) {
      for (let c = 0; c < SIZE; c++) {
        if (b[r][c] === 0) cells.push([r, c]);
      }
    }
    return cells;
  }

  function spawnTile() {
    const cells = getEmptyCells(board);
    if (cells.length === 0) return false;
    const [r, c] = cells[Math.floor(Math.random() * cells.length)];
    board[r][c] = Math.random() < 0.9 ? 2 : 4;
    return true;
  }

  function render() {
    boardEl.innerHTML = '';
    for (let r = 0; r < SIZE; r++) {
      for (let c = 0; c < SIZE; c++) {
        const v = board[r][c];
        const cell = document.createElement('div');
        cell.className = 'cell';
        cell.setAttribute('data-v', v);
        cell.textContent = v === 0 ? '' : v;
        boardEl.appendChild(cell);
      }
    }
    scoreEl.textContent = score;
  }

  function reset() {
    board = emptyBoard();
    score = 0;
    spawnTile();
    spawnTile();
    render();
  }

  // Merge a single line (array of length SIZE) toward the "left" end (index 0).
  // Returns { line: newArray, gained: number, moved: boolean(compared later) }
  function mergeLine(arr) {
    const filtered = arr.filter(v => v !== 0);
    const result = [];
    let gained = 0;
    let i = 0;
    while (i < filtered.length) {
      if (i + 1 < filtered.length && filtered[i] === filtered[i + 1]) {
        const merged = filtered[i] * 2;
        result.push(merged);
        gained += merged;
        i += 2;
      } else {
        result.push(filtered[i]);
        i += 1;
      }
    }
    while (result.length < SIZE) result.push(0);
    return { line: result, gained };
  }

  function arraysEqual(a, b) {
    for (let i = 0; i < a.length; i++) {
      if (a[i] !== b[i]) return false;
    }
    return true;
  }

  function move(direction) {
    const newBoard = emptyBoard();
    let moved = false;
    let totalGained = 0;

    if (direction === 'left') {
      for (let r = 0; r < SIZE; r++) {
        const row = board[r];
        const { line, gained } = mergeLine(row);
        if (!arraysEqual(row, line)) moved = true;
        newBoard[r] = line;
        totalGained += gained;
      }
    } else if (direction === 'right') {
      for (let r = 0; r < SIZE; r++) {
        const row = board[r];
        const reversed = row.slice().reverse();
        const { line, gained } = mergeLine(reversed);
        const finalLine = line.reverse();
        if (!arraysEqual(row, finalLine)) moved = true;
        newBoard[r] = finalLine;
        totalGained += gained;
      }
    } else if (direction === 'up') {
      for (let c = 0; c < SIZE; c++) {
        const col = [board[0][c], board[1][c], board[2][c], board[3][c]];
        const { line, gained } = mergeLine(col);
        if (!arraysEqual(col, line)) moved = true;
        for (let r = 0; r < SIZE; r++) newBoard[r][c] = line[r];
        totalGained += gained;
      }
    } else if (direction === 'down') {
      for (let c = 0; c < SIZE; c++) {
        const col = [board[0][c], board[1][c], board[2][c], board[3][c]];
        const reversed = col.slice().reverse();
        const { line, gained } = mergeLine(reversed);
        const finalLine = line.reverse();
        if (!arraysEqual(col, finalLine)) moved = true;
        for (let r = 0; r < SIZE; r++) newBoard[r][c] = finalLine[r];
        totalGained += gained;
      }
    } else {
      return false;
    }

    if (moved) {
      board = newBoard;
      score += totalGained;
      spawnTile();
      render();
    }
    return moved;
  }

  function setBoard(arr) {
    board = arr.map(row => row.slice());
    render();
  }

  window.game = {
    size: SIZE,
    reset,
    move,
    board: () => board.map(row => row.slice()),
    setBoard,
    score: () => score,
  };

  resetBtn.addEventListener('click', reset);

  const keyMap = {
    'ArrowLeft': 'left',
    'ArrowRight': 'right',
    'ArrowUp': 'up',
    'ArrowDown': 'down',
  };

  window.addEventListener('keydown', (e) => {
    const dir = keyMap[e.key];
    if (dir) {
      e.preventDefault();
      move(dir);
    }
  });

  reset();
})();
</script>

</body>
</html>
